cat > RunnerUITests/BlueskyUITests.swift <<'EOF'
import XCTest

final class BlueskyUITests: XCTestCase {
    func testChooseQuotePost() {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
        let quote = app.buttons.matching(NSPredicate(format: "label == %@", "Quote post")).firstMatch
        XCTAssertTrue(quote.waitForExistence(timeout: 10), "Quote post is not available")
        quote.tap()
    }
