import XCTest

final class BlueskyUITests: XCTestCase {
    func testFinalizeQuotePost() {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
        let editor = app.textViews.firstMatch
        XCTAssertTrue(editor.waitForExistence(timeout: 10))
        editor.tap()
        let existing = editor.value as? String ?? ""
        print("Current quote text: \(existing)")
        if !existing.isEmpty {
            editor.typeText(String(repeating: XCUIKeyboardKey.delete.rawValue, count: existing.count))
        }
        editor.typeText("sharing this")
        XCTAssertEqual(editor.value as? String, "sharing this")
        XCUIScreen.main.coordinate(withNormalizedOffset: CGVector(dx: 0.90, dy: 0.11)).tap()
    }
}
EOF
xcodebuild test -quiet -project BlueskyUITap.xcodeproj -scheme BlueskyUITap -destination 'platform=iOS Simulator,id=393CFCE7-506A-4455-B8B8-6F430DABBFCE' -resultBundlePath FinalizeResults.xcresult

